def transform(grid):
    # Each color's points define diagonal line segments; connect nearest matching diagonal points.
    out=[r[:] for r in grid]
    for color in (1,6):
        pts=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==color]
        pairs=[]
        for i,(r,c) in enumerate(pts):
            for s,d in pts[i+1:]:
                if abs(s-r)==abs(d-c) and s!=r:
                    pairs.append((abs(s-r),r,c,s,d))
        # connect each endpoint along its nearest diagonal partner
        used=set()
        for dist,r,c,s,d in sorted(pairs):
            if (r,c) in used or (s,d) in used: continue
            used|={(r,c),(s,d)}
            dr=1 if s>r else -1; dc=1 if d>c else -1
            x,y=r,c
            while (x,y)!=(s,d):
                x+=dr;y+=dc
                if out[x][y]==4:out[x][y]=color
    return out
